import type { WorkerConfig } from './config.js'
import { workerMcpEnv } from './config.js'

// The selection rules and redactText are copied from scrum4me-docker lib/log-redact.ts:9-58 (52ded13):
// the full value of a variable whose name matches the pattern, plus the password of every URL value
// (raw and decoded). Only values of 8+ chars are redacted, longest first, replaced by '***'.
// The stream rule buffer (:60-88) is not needed here.
export const REDACTED = '***'

const SECRET_NAME_RE = /(TOKEN|SECRET|PASSWORD|PASSWD|API_KEY|PRIVATE_KEY|_KEY$|DSN|CREDENTIAL)/i

/** Alle kandidaten ... */
export function collectSecretEntries(...envs: Array<Record<string, string | undefined>>): { name: string; value: string }[] {
  const entries: { name: string; value: string }[] = []
  for (const env of envs) {
    for (const [key, value] of Object.entries(env)) {
      if (!value) continue
      if (SECRET_NAME_RE.test(key)) entries.push({ name: key, value })
      // The password of a URL value, raw and decoded, even under a non-secret key.
      try {
        const url = new URL(value)
        const raw = url.password
        if (!raw) continue
        entries.push({ name: `${key} (url-wachtwoord)`, value: raw })
        let decoded: string
        try { decoded = decodeURIComponent(raw) } catch { continue }
        if (decoded !== raw && decoded) entries.push({ name: `${key} (url-wachtwoord)`, value: decoded })
      } catch {
        // Not a URL value.
      }
    }
  }
  return entries
}
```

